      configcerts: [{ method: "GET", path: "/v1/config-cert-reviews" }, { method: "POST", path: "/v1/config-cert-reviews" }, { method: "GET", path: "/v1/config-cert-reviews/:reviewId" }, { method: "POST", path: "/v1/config-cert-reviews/:reviewId/complete" }],
      endorsement: [{ method: "GET", path: "/v1/endorsement/peers" }, { method: "GET", path: "/v1/endorsement/peers/:peerId" }, { method: "POST", path: "/v1/endorsement/peers/:peerId/quarantine" }, { method: "GET", path: "/v1/endorsement/decisions" }],
      erasures: [{ method: "GET", path: "/v1/erasures" }, { method: "POST", path: "/v1/erasures" }, { method: "GET", path: "/v1/erasures/:jobId" }, { method: "GET", path: "/v1/erasure-drills" }, { method: "POST", path: "/v1/erasure-drills" }, { method: "GET", path: "/v1/erasure-drills/:drillId" }],
